for intent,q,a,p,route,setup,policy in POLICY_ROWS:
    add(intent,q,a,[p],route,limits=['This is a labelled engineering policy/state/failure scenario, not a new OEM procedure.'])
    ROWS[-1]['scenario_setup']=setup
    ROWS[-1]['policy_refs']=[policy]
    ROWS[-1]['case_type']='engineering_policy_regression'

def main():
    context=json.loads((HOME/'batch_context.json').read_bytes())
    pinned=context.get('context_sha256') or context.get('batch_context_sha256')
    if not pinned:
        pinned=hashlib.sha256(workflow.encoded(context)).hexdigest()
    text=(HOME/'source_views/author/manual_pymupdf_text.txt').read_text(encoding='utf-8')
    for i,row in enumerate(ROWS,1):
        rid=f'GEN{i:03d}'
        refs=[]
        for p in row.pop('pages'):
            section=text.split(f'=== PDF PAGE {p} ===\n',1)[1].split('=== PDF PAGE',1)[0].strip()
            refs.append({'pdf_page':p,'printed_page':str(p-2),'checked_span':section,'evidence_ids':[],'inspection_method':'Original PDF page text read independently by author; figures not used for an unverified procedural claim.'})
        follow=row.pop('follow')
        payload={'record_id':rid,'version':1,'role':'author','actor':'batch100-author','manual_sha256':workflow.MANUAL_SHA,'batch_context_sha256':pinned,'origin_declaration':workflow.ORIGIN,'status':'DRAFT_ENGINEERING_ONLY','source_refs':refs,'stopping_rules':['Withhold runtime technical advice until actual applicability, independent source/dependency, rights and final claim gates pass.','Do not repeat attempted actions without a documented exception or superseding correction.','Escalate unsupported procedures to authorised Royal Enfield support; customer resolution is reported, not mechanically verified.'],'forbidden_claims':['No inferred hidden diagnosis, invented thresholds, repair instructions or OEM next-step order.','Agent consensus is not human acceptance, formal source approval, public display permission or release.'],'turns':[{'speaker':'rider','text':row['question']},{'speaker':'assistant','text':row['answer']}]+follow,**row}
        if payload['expected_route']=='SUPPORTED': payload['conditions'].insert(0,'Confirmed applicable Himalayan BS6 and immutable selected manual; this expected route is conditional, not runtime authorization.')
        path=HOME/'drafts'/f'{rid}_v1.json'
        if path.exists(): continue
        with path.open('xb') as f:f.write(workflow.encoded(payload))
        print(rid,hashlib.sha256(path.read_bytes()).hexdigest())
if __name__=='__main__':main()
